     3	import static com.sun.fortress.exceptions.ProgramError.error;
     4	import com.sun.fortress.compiler.runtimeValues.FortressImplementationError;
     5	import com.sun.fortress.exceptions.FortressError;
     6	import com.sun.fortress.interpreter.Driver;
     7	import com.sun.fortress.interpreter.evaluator.values.*;
     8	import com.sun.fortress.nodes.*;
     9	import com.sun.fortress.nodes_util.NodeUtil;
    10	import edu.rice.cs.plt.tuple.Option;
    11	
    12	import java.lang.reflect.InvocationTargetException;
    13	import java.lang.reflect.Method;
    14	import java.lang.reflect.Modifier;
    15	import java.math.BigInteger;
    16	import java.util.ArrayList;
    17	import java.util.List;
    18	import java.util.regex.Matcher;
    19	import java.util.regex.Pattern;
    20	
    21	/**
    22	 * A native whose builtinPrimitive string names a static Java method of the
    23	 * package com.sun.fortress.nativeHelpers, "com.sun.fortress.nativeHelpers.Class.method",
    24	 * in place of a glue class.  Among the class's public static methods of that
    25	 * name it takes the one whose Java parameter and result types carry the
    26	 * declaration's types; a functional method's self, and a dotted method's self,
    27	 * go first.  It calls the method by reflection, each argument unboxed and the
    28	 * result boxed at the declared result type.  A helper's raise of an exception
    29	 * class of the compiled path, "fortress.<Api>$<Name>", becomes the raise of the
    30	 * library's own exception object <Name>, as Int.overflow() raises IntegerOverflow.
    31	 */
    32	public class StaticNativeApp extends NativeMeth {
    33	    public static final String HELPERS = "com.sun.fortress.nativeHelpers.";
    34	
    35	    /** Does s name a helper (a static method of nativeHelpers), not a glue class? */
    36	    public static boolean isHelperString(String s) {
    37	        return s.startsWith(HELPERS);
    38	    }
    39	
    40	    private final Method m;
    41	    private final Class<?>[] ps;
    42	    private final String result;     // the declared result type's name
    43	    private final int selfAt;        // index of self among the declared parameters, or -1
    44	    private int arity;
    45	
    46	    /** The Java type that carries a value of the named Fortress type, or null. */
    47	    static Class<?> javaFor(String t) {
    48	        if (t == null) return null;
    49	        if (t.equals("ZZ32") || t.equals("NN32") || t.equals("Char")) return int.class;
    50	        if (t.equals("ZZ64") || t.equals("NN64")) return long.class;
    51	        if (t.equals("RR64") || t.equals("Float")) return double.class;
    52	        if (t.equals("RR32")) return float.class;
    53	        if (t.equals("Boolean")) return boolean.class;
    54	        if (t.equals("String") || t.equals("FlatString") || t.equals("JavaString")) return String.class;
    55	        if (t.equals("ZZ")) return BigInteger.class;
    56	        if (t.equals("()")) return void.class;
    57	        return null;
    58	    }
    59	
    60	    static String typeName(TypeOrPattern t) {
    61	        if (t instanceof TupleType && ((TupleType) t).getElements().isEmpty()) return "()";
    62	        if (t instanceof NamedType) return ((NamedType) t).getName().getText();
    63	        return null;
    64	    }
    65	
    66	    static boolean hasResultType(Applicable defn) {
    67	        Option<Type> r = NodeUtil.getReturnType(defn);
    68	        return r != null && r.isSome();
    69	    }
    70	
    71	    /** The name of the declared result type, or null. */
    72	    static String declaredResult(Applicable defn) {
    73	        return hasResultType(defn) ? typeName(NodeUtil.getReturnType(defn).unwrap()) : null;
    74	    }
    75	
    76	    static boolean carried(Class<?> c) {
    77	        return c == int.class || c == long.class || c == double.class || c == float.class
    78	            || c == boolean.class || c == String.class || c == BigInteger.class;
    79	    }
    80	
    81	    /**
    82	     * The Java type that carries self, a value of the declaring type named t, or null: a type of
    83	     * FortressLibrary or FortressBuiltin, whose names no program can give its own types, that javaFor
    84	     * names, or the object Int, Long, UnsignedLong, Float or BigNum.  FlatString and JavaString, names
    85	     * that a program can give its own types, carry no self.
    86	     */
    87	    static Class<?> javaForSelf(String t) {
    88	        if (t == null || t.equals("FlatString") || t.equals("JavaString")) return null;
    89	        if (t.equals("Int")) return int.class;
    90	        if (t.equals("Long") || t.equals("UnsignedLong")) return long.class;
    91	        if (t.equals("Float")) return double.class;
    92	        if (t.equals("BigNum")) return BigInteger.class;
    93	        Class<?> c = javaFor(t);
    94	        return c == void.class ? null : c;
    95	    }
    96	
    97	    /**
    98	     * The helper that the string s names for the declaration defn, or an error message.  Among the
    99	     * class's public static methods of that name, it takes the one whose parameters are the
   100	     * declaration's, self first where the declaration has one (a functional method), or one more
   101	     * in front for a dotted method's self, at the Java types that carry the declared types.
   102	     */
   103	    static Object find(String s, Applicable defn) {
   104	        return find(s, defn, null);
   105	    }
   106	
   107	    /**
   108	     * As find(s, defn), where the declaration is a method of the type named declarer, whose value
   109	     * is self: it refuses a declarer that no Java type carries, and takes only an overload whose
   110	     * first Java parameter is the declarer's carrier.
   111	     */
   112	    static Object find(String s, Applicable defn, String declarer) {
   113	        int dot = s.lastIndexOf('.');
   114	        String cls = s.substring(0, dot), name = s.substring(dot + 1);
   115	        Class<?> c;
   116	        try { c = Class.forName(cls); }
   117	        catch (ClassNotFoundException e) { return "Native helper class " + cls + " not found."; }
   118	        List<Method> named = new ArrayList<Method>();
   119	        for (Method x : c.getMethods())
   120	            if (x.getName().equals(name) && Modifier.isStatic(x.getModifiers())) named.add(x);
   121	        if (named.isEmpty()) return "Native helper " + s + " names no static method of " + cls + ".";
   122	        List<Class<?>> want = new ArrayList<Class<?>>();
   123	        boolean hasSelf = false;
   124	        for (Param p : NodeUtil.getParams(defn)) {
   125	            String pn = p.getName().getText();
   126	            if (pn.equals("self")) { hasSelf = true; continue; }
   127	            Class<?> j = javaFor(p.getIdType().isSome() ? typeName(p.getIdType().unwrap()) : null);
   128	            if (j == null || j == void.class)
   129	                return "Native helper " + s + ": no Java type carries the declared type of parameter " + pn + ".";
   130	            want.add(j);
   131	        }
   132	        Class<?> res = null;    // a declaration without a result type is refused by NativeApp.init
   133	        if (hasResultType(defn)) {
   134	            res = javaFor(declaredResult(defn));
   135	            if (res == null) return "Native helper " + s + ": no Java type carries the declared result type.";
   136	        }
   137	        Class<?> selfJava = null;
   138	        if (declarer != null) {
   139	            selfJava = javaForSelf(declarer);
   140	            if (selfJava == null)
   141	                return "Native helper " + s + ": no Java type carries " + declarer + ", the type of self.";
   142	        }
   143	        List<Method> fits = new ArrayList<Method>();
   144	        for (Method x : named) {
   145	            Class<?>[] xs = x.getParameterTypes();
   146	            int off = xs.length - want.size();          // 1: self first
   147	            if (off < 0 || off > 1 || ((hasSelf || selfJava != null) && off != 1)) continue;
   148	            boolean ok = (res == null || x.getReturnType() == res)
   149	                         && (x.getReturnType() == void.class || carried(x.getReturnType()));
   150	            for (int i = 0; ok && i < xs.length; i++) {
   151	                if (!carried(xs[i])) ok = false;
   152	                else if (i >= off && xs[i] != want.get(i - off)) ok = false;
   153	            }
   154	            if (ok && selfJava != null && xs[0] != selfJava) ok = false;
   155	            if (ok) fits.add(x);
   156	        }
   157	        if (fits.size() == 1) return fits.get(0);
   158	        if (fits.isEmpty()) return "Native helper " + s + " has no overload that fits the declaration's types.";
   159	        return "Native helper " + s + " has " + fits.size() + " overloads that fit the declaration's types.";
   160	    }
   161	
   162	    StaticNativeApp(Method m, Applicable defn) {
   163	        this.m = m;
   164	        this.ps = m.getParameterTypes();
   165	        this.result = declaredResult(defn);
   166	        int at = -1, i = 0;
   167	        for (Param p : NodeUtil.getParams(defn)) { if (p.getName().getText().equals("self")) at = i; i++; }
   168	        this.selfAt = at;
   169	    }
   170	
   171	    public int getArity() { return arity; }
   172	
   173	    protected void init(Applicable app, boolean isFunctionalMethod) {
   174	        arity = NodeUtil.getParams(app).size() - (isFunctionalMethod ? 1 : 0);
   175	        super.init(app, isFunctionalMethod);
   176	    }
   177	
   178	    /** A function, or a functional method with its self among the arguments: self goes first. */
   179	    public FValue applyToArgs(List<FValue> args) {
   180	        if (selfAt <= 0) return call(args);
   181	        List<FValue> all = new ArrayList<FValue>(args);
   182	        all.add(0, all.remove(selfAt));
   183	        return call(all);
   184	    }
   185	
   186	    /** A dotted method: self first. */
   187	    public FValue applyMethod(FObject self, List<FValue> args) {
   188	        List<FValue> all = new ArrayList<FValue>(args.size() + 1);
   189	        all.add(self);
   190	        all.addAll(args);
   191	        return call(all);
   192	    }
   193	
   194	    private FValue call(List<FValue> args) {
   195	        if (args.size() != ps.length) return error("Native " + m + " given " + args.size() + " arguments");
   196	        Object[] xs = new Object[ps.length];
   197	        for (int i = 0; i < ps.length; i++) xs[i] = unbox(ps[i], args.get(i));
   198	        try {
   199	            return box(m.getReturnType(), result, m.invoke(null, xs));
   200	        }
   201	        catch (InvocationTargetException e) {
   202	            Throwable t = e.getCause();
   203	            FortressError f = raised(t);
   204	            if (f != null) throw f;
   205	            if (t instanceof RuntimeException) throw (RuntimeException) t;
   206	            if (t instanceof Error) throw (Error) t;
   207	            return error(t.toString());
   208	        }
   209	        catch (IllegalAccessException e) {
   210	            return error(e.toString());
   211	        }
   212	    }
   213	
   214	    private static final Pattern RAISE = Pattern.compile("^fortress\\.\\w+\\$(\\w+)$");
   215	
   216	    /** A helper's Utility.makeFortressException("fortress.<Api>$<Name>") names a compiled class;
   217	        under walk it becomes the library's own exception object <Name>. */
   218	    static FortressError raised(Throwable t) {
   219	        if (!(t instanceof FortressImplementationError) || t.getMessage() == null) return null;
   220	        Matcher x = RAISE.matcher(t.getMessage());
   221	        if (!x.matches()) return null;
   222	        return new FortressError((FObject) Driver.getFortressLibrary().getRootValue(x.group(1)));
   223	    }
   224	
   225	    static Object unbox(Class<?> c, FValue v) {
   226	        if (c == int.class) return v instanceof FChar ? ((FChar) v).getChar() : v.getInt();
   227	        if (c == long.class) return v.getLong();
   228	        if (c == double.class) return v.getFloat();
   229	        if (c == float.class) return (float) v.getFloat();
   230	        if (c == boolean.class) return ((FBool) v).getBool();
   231	        if (c == String.class) return v.getString();
   232	        if (c == BigInteger.class) return v.getBigInteger();
   233	        return error("No interpreter value for a Java " + c.getName());
   234	    }
   235	
   236	    /** The result at the declared type: int as ZZ32, NN32 or Char; long as ZZ64 or NN64. */
   237	    static FValue box(Class<?> c, String declared, Object r) {
   238	        if (c == void.class) return FVoid.V;
   239	        if (c == int.class) {
   240	            int i = (Integer) r;
   241	            if ("NN32".equals(declared)) return FNN32.make(i);
   242	            if ("Char".equals(declared)) return FChar.make(i);
   243	            return FInt.make(i);
   244	        }
   245	        if (c == long.class) {
   246	            long l = (Long) r;
   247	            if ("NN64".equals(declared)) return FNN64.make(l);
   248	            return FLong.make(l);
   249	        }
   250	        if (c == double.class) return FFloat.make((Double) r);
   251	        if (c == float.class) return FRR32.make((Float) r);
   252	        if (c == boolean.class) return FBool.make((Boolean) r);
   253	        if (c == String.class) return FString.make((String) r);
   254	        if (c == BigInteger.class) return FBigNum.make((BigInteger) r);
   255	        return error("No interpreter value for a Java " + c.getName());
   256	    }
   257	}

