1	package com.sun.fortress.compiler;
2	
3	import com.sun.fortress.nodes.*;
4	import com.sun.fortress.nodes_util.ExprFactory;
5	import com.sun.fortress.nodes_util.NodeFactory;
6	import com.sun.fortress.nodes_util.NodeUtil;
7	import com.sun.fortress.nodes_util.Span;
8	import edu.rice.cs.plt.tuple.Option;
9	
10	import java.lang.reflect.Method;
11	import java.lang.reflect.Modifier;
12	import java.util.*;
13	
14	/**
15	 * The compiled path's reading of a native binding.  A declaration whose body is
16	 * exactly builtinPrimitive("pkg.Class.method"), the tight juxtaposition that walk's
17	 * NativeApp.checkAndLoadNative recognizes, where the string names a public static
18	 * method of a class of the helpers' package, com.sun.fortress.nativeHelpers., becomes
19	 * a call of that method through the import java machinery: the component gains
20	 * import java pkg.{Class.method => alias}, and the body becomes alias(args), the
21	 * parameters in order, self first for a method of a trait or object (a dotted
22	 * method's self added, a functional method's moved to the front), as walk's
23	 * NativeMeth passes them.  Where the declaration gives an argument or the result
24	 * the type NN32, NN64 or Char (Character in the compiler's prelude), and the helper's
25	 * Java type there is an int or a long, which the checker reads as ZZ32 or ZZ64, that
26	 * argument or the call goes through the matching one of the six transfer helpers,
27	 * whose names the checker reads at the declared type (NamingCzar), as the prelude
28	 * composes them: makeNN32FromZZ32(unsignedIntOverflowingAdd(makeZZ32FromNN32(self),
29	 * makeZZ32FromNN32(b))); a position that the helper's own name already reads at the
30	 * declared type, as each transfer's, gets none.  A declaration with a varargs
31	 * parameter is left alone.
32	 * A string under the helpers' package that names no public static method is a
33	 * static error at the string.  Any other string is left alone, walk's glue classes
34	 * ("pkg.Class$Op") among them, so that its body stays a call of builtinPrimitive.
35	 *
36	 * Shell.specificRepository turns it on for the compiled path's repository and off
37	 * for walk's, which loads such a body itself.  Parser applies it to the parse of a
38	 * component (parseFileConvertExn) and to the import collector's view of a component
39	 * that names a helper (importCollector), so that the repository knows the foreign
40	 * api when it builds its graph, before every phase.
41	 */
42	public final class BuiltinPrimitiveRewriter {
43	    private BuiltinPrimitiveRewriter() {}
44	
45	    public static final String HELPERS = "com.sun.fortress.nativeHelpers.";
46	    private static volatile boolean on = false;
47	    public static void setEnabled(boolean b) { on = b; }
48	    public static boolean enabled() { return on; }
49	
50	    /** pkg -> (Class.method -> alias), in order of first use */
51	    private static final class Aliases extends LinkedHashMap<String, LinkedHashMap<String, String>> {}
52	
53	    /** The component with each binding that names a static method rewritten; any other unit as it is. */
54	    public static CompilationUnit rewrite(CompilationUnit cu) {
55	        if (!enabled() || !(cu instanceof Component)) return cu;
56	        Component c = (Component) cu;
57	        Aliases aliases = new Aliases();
58	        List<Decl> decls = new ArrayList<Decl>();
59	        for (Decl d : c.getDecls()) decls.add(decl(d, null, aliases));
60	        if (aliases.isEmpty()) return cu;
61	        List<Import> imports = new ArrayList<Import>(c.getImports());
62	        Span span = NodeUtil.getSpan(c);
63	        for (Map.Entry<String, LinkedHashMap<String, String>> e : aliases.entrySet()) {
64	            List<AliasedSimpleName> names = new ArrayList<AliasedSimpleName>();
65	            for (Map.Entry<String, String> n : e.getValue().entrySet())
66	                names.add(NodeFactory.makeAliasedSimpleName(span, NodeFactory.makeId(span, n.getKey()),
67	                          Option.<IdOrOpOrAnonymousName>some(NodeFactory.makeId(span, n.getValue()))));
68	            imports.add(NodeFactory.makeImportNames(span, Option.some("java"),
69	                                                    NodeFactory.makeAPIName(span, e.getKey()), names));
70	        }
71	        return new Component(c.getInfo(), c.getName(), imports, decls, c.getComprises(), c.is_native(), c.getExports());
72	    }
73	
74	    /** owner: the simple name of the enclosing trait or object, "" for a generic one, null at the top level */
75	    private static Decl decl(Decl d, String owner, Aliases aliases) {
76	        if (d instanceof FnDecl) return fn((FnDecl) d, owner, aliases);
77	        if (d instanceof TraitDecl) {
78	            TraitDecl t = (TraitDecl) d;
79	            return new TraitDecl(t.getInfo(), header(t.getHeader(), aliases), t.getSelfType(),
80	                                 t.getExcludesClause(), t.getComprisesClause(), t.isComprisesEllipses());
81	        }
82	        if (d instanceof ObjectDecl) {
83	            ObjectDecl o = (ObjectDecl) d;
84	            return new ObjectDecl(o.getInfo(), header(o.getHeader(), aliases), o.getSelfType());
85	        }
86	        return d;
87	    }
88	
89	    private static TraitTypeHeader header(TraitTypeHeader h, Aliases aliases) {
90	        List<Decl> ds = new ArrayList<Decl>();
91	        String owner = h.getStaticParams().isEmpty() ? NodeUtil.nameString(h.getName()) : "";
92	        for (Decl d : h.getDecls()) ds.add(decl(d, owner, aliases));
93	        return new TraitTypeHeader(h.getStaticParams(), h.getMods(), h.getName(), h.getWhereClause(),
94	                                   h.getThrowsClause(), h.getContract(), h.getExtendsClause(), h.getParams(), ds);
95	    }
96	
97	    private static FnDecl fn(FnDecl f, String owner, Aliases aliases) {
98	        boolean inType = owner != null;
99	        if (f.getBody().isNone() || !(f.getBody().unwrap() instanceof Juxt)) return f;
100	        Juxt body = (Juxt) f.getBody().unwrap();
101	        List<Expr> es = body.getExprs();
102	        if (!body.isTight() || es.size() != 2 || !(es.get(0) instanceof VarRef) || !(es.get(1) instanceof StringLiteralExpr))
103	            return f;
104	        if (!((VarRef) es.get(0)).getVarId().getText().equals("builtinPrimitive")) return f;
105	        String s = ((StringLiteralExpr) es.get(1)).getText();
106	        if (!s.startsWith(HELPERS)) return f;
107	        int m = s.lastIndexOf('.'), k = s.lastIndexOf('.', m - 1);
108	        if (!namesStaticMethod(s.substring(0, m), s.substring(m + 1)))
109	            throw com.sun.fortress.exceptions.StaticError.make(
110	                "builtinPrimitive names no static helper: " + s, es.get(1));
111	
112	        Span span = NodeUtil.getSpan(body);
113	        List<Expr> args = new ArrayList<Expr>();
114	        List<String> declared = new ArrayList<String>();   // each argument's declared type, by simple name
115	        boolean hasSelf = false;
116	        for (Param p : NodeUtil.getParams(f)) {
117	            if (p.getVarargsType().isSome()) return f;
118	            if (p.getName().getText().equals("self")) hasSelf = true;
119	            else {
120	                args.add(ExprFactory.makeVarRef(span, p.getName().getText()));
121	                declared.add(simpleName(p.getIdType().isSome() ? p.getIdType().unwrap() : null));
122	            }
123	        }
124	        if (inType || hasSelf) {
125	            args.add(0, ExprFactory.makeVarRef(span, "self"));
126	            declared.add(0, owner);
127	        }
128	
129	        String pkg = s.substring(0, k), item = s.substring(k + 1);   // item = Class.method
130	        String alias = alias(aliases, pkg, item);
131	
132	        /* Where the declaration gives a position a type that the helper's Java type carries but the
133	         * foreign-type table reads otherwise (an int as NN32 or Char, a long as NN64), the call goes
134	         * through the transfer helpers, whose special names the table reads (NamingCzar). */
135	        Method jm = soleMethod(s.substring(0, m), s.substring(m + 1), args.size());
136	        String helperName = s.substring(m + 1);
137	        if (jm != null) {
138	            Class<?>[] pts = jm.getParameterTypes();
139	            for (int i = 0; i < args.size(); i++) {
140	                String t = transfer(declared.get(i), pts[i], helperName, false);
141	                if (t != null)
142	                    args.set(i, ExprFactory.makeTightJuxt(span, ExprFactory.makeVarRef(span, alias(aliases, HELPERS.substring(0, HELPERS.length() - 1), t)),
143	                                                          ExprFactory.makeInParentheses(args.get(i))));
144	            }
145	        }
146	
147	        Expr arg = args.isEmpty() ? ExprFactory.makeVoidLiteralExpr(span)
148	                 : args.size() == 1 ? ExprFactory.makeInParentheses(args.get(0))
149	                 : ExprFactory.makeTupleExpr(span, args);
150	        Expr call = ExprFactory.makeTightJuxt(body, Arrays.asList(ExprFactory.makeVarRef(span, alias), arg));
151	        if (jm != null && f.getHeader().getReturnType().isSome()) {
152	            String t = transfer(simpleName(f.getHeader().getReturnType().unwrap()), jm.getReturnType(), helperName, true);
153	            if (t != null)
154	                call = ExprFactory.makeTightJuxt(span, ExprFactory.makeVarRef(span, alias(aliases, HELPERS.substring(0, HELPERS.length() - 1), t)),
155	                                                 ExprFactory.makeInParentheses(call));
156	        }
157	        return new FnDecl(f.getInfo(), f.getHeader(), f.getUnambiguousName(), Option.some(call),
158	                          f.getImplementsUnambiguousName());
159	    }
160	
161	    private static String alias(Aliases aliases, String pkg, String item) {
162	        LinkedHashMap<String, String> inPkg = aliases.get(pkg);
163	        if (inPkg == null) aliases.put(pkg, inPkg = new LinkedHashMap<String, String>());
164	        String alias = inPkg.get(item);
165	        if (alias == null) inPkg.put(item, alias = "builtinPrimitive_" + item.replace('.', '_'));
166	        return alias;
167	    }
168	
169	    private static String simpleName(Object t) {
170	        if (t instanceof TraitType && ((TraitType) t).getArgs().isEmpty()) return ((TraitType) t).getName().getText();
171	        if (t instanceof VarType) return ((VarType) t).getName().getText();
172	        return null;
173	    }
174	
175	    /** The transfer helper, Class.method, that carries a declared type in the Java type c where the table reads c otherwise. */
176	    private static String transfer(String declared, Class<?> c, String helper, boolean result) {
177	        if (declared == null) return null;
178	        String desc = c == int.class ? "I" : c == long.class ? "J" : null;
179	        if (desc == null) return null;
180	        com.sun.fortress.nodes.Type read = NamingCzar.fortressTypeForForeignJavaType(desc, helper, result);
181	        String r = simpleName(read);
182	        if (declared.equals(r)) return null;
183	        if (desc.equals("I") && declared.equals("NN32"))
184	            return result ? "simpleUnsignedIntArith.makeNN32FromZZ32WithSpecialCompilerHackForNN32ResultType"
185	                          : "simpleUnsignedIntArith.makeZZ32FromNN32WithSpecialCompilerHackForNN32ArgumentType";
186	        if (desc.equals("I") && (declared.equals("Char") || declared.equals("Character")))
187	            return result ? "simpleChar.charMakeCharacterWithSpecialCompilerHackForCharacterResultType"
188	                          : "simpleChar.charCodePointWithSpecialCompilerHackForCharacterArgumentType";
189	        if (desc.equals("J") && declared.equals("NN64"))
190	            return result ? "simpleUnsignedLongArith.makeNN64FromZZ64WithSpecialCompilerHackForNN64ResultType"
191	                          : "simpleUnsignedLongArith.makeZZ64FromNN64WithSpecialCompilerHackForNN64ArgumentType";
192	        return null;
